"""Export the fitted coefficients the app needs to app/static/models.js (a plain script, so the static page also works when opened from a file).
Run after any change of the models: python app/export_models.py"""
import json, os, sys
import numpy as np, pandas as pd
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__))); DQ = os.path.join(ROOT, "research", "dq")
def lst(m): return dict(F=list(m["F"]), mu=np.asarray(m["mu"], float).tolist(), sd=np.asarray(m["sd"], float).tolist(), b=np.asarray(m["b"], float).tolist())
v5, v6, hz, v15, v16 = (pd.read_pickle(os.path.join(DQ, f)) for f in ("v5_models.pkl", "v6_models.pkl", "tf_model.pkl", "v15_models.pkl", "v16_models.pkl")); v13 = pd.read_pickle(os.path.join(DQ, "v13_models.pkl"))
def part(m): return dict(mu=np.asarray(m["mu"], float).tolist(), sd=np.asarray(m["sd"], float).tolist(), b=np.asarray(m["b"], float).tolist())
M = dict(xg=lst(v5["xG_geo"]), cont=lst(v6["cont"]), xa=lst(v16["xA_chain_all"]), L=dict(F=list(v15["L"]["F"]), opp=part(v15["L"]["opp"]), own=part(v15["L"]["own"])),
         hz=dict(mu=np.asarray(hz["mu"], float).tolist(), sd=np.asarray(hz["sd"], float).tolist(), b=np.asarray(hz["b"], float).tolist()), C=float(v15["C"]), Qhi=float(v13["Q_hi"]))
out = os.path.join(ROOT, "app", "static", "models.js"); open(out, "w").write("// generated by app/export_models.py from research/dq/*.pkl; do not edit\nwindow.DS_MODELS=" + json.dumps(M) + ";\n"); print("wrote", out, os.path.getsize(out), "bytes")
